head.script:
// SCORM 1.2 API adapter (window.API), persisted via /scorm/commit
(function () {
    var packageId = ;
    var cmi = {
        "cmi.core.lesson_status": ,
        "cmi.suspend_data": ,
        "cmi.core.score.raw": ""
    };
    var dirty = false;
    function commit() {
        if (!dirty) return "true";
        dirty = false;
        fetch("/scorm/commit/" + packageId, {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({
                jsonrpc: "2.0", method: "call",
                params: {
                    lesson_status: cmi["cmi.core.lesson_status"],
                    score_raw: cmi["cmi.core.score.raw"],
                    suspend_data: cmi["cmi.suspend_data"]
                }
            })
        });
        return "true";
    }
    window.API = {
        LMSInitialize: function () { return "true"; },
        LMSFinish: function () { return commit(); },
        LMSGetValue: function (k) { return cmi[k] || ""; },
        LMSSetValue: function (k, v) { cmi[k] = String(v); dirty = true; return "true"; },
        LMSCommit: function () { return commit(); },
        LMSGetLastError: function () { return "0"; },
        LMSGetErrorString: function () { return "No error"; },
        LMSGetDiagnostic: function () { return ""; }
    };
    window.addEventListener("beforeunload", commit);
})();
